import inspect
import importlib
import logging
from taf.ue.tm500.asc.command import versions
from taf.ue.tm500.asc.command.versions.v0_0_0 import GetVersion
from taf.ue.tm500.asc.command.base import Command


class CommandsSelector:
    def __init__(self, connection):
        self._connection = connection
        self._versions = self._import_all_supported_versions()
        logging.info(f"versions in white list are {self._versions.keys()}, 0.0.0 is a default solution for the versions older than "
                     "the smallest version in the white list"
                     )

    def _import_all_supported_versions(self):
        return {version[1:].replace('_', '.'): importlib.import_module('.' + version,
                                                                       'taf.ue.tm500.asc.command.versions')
                for version in versions.__all__}

    def select(self, version=None):
        sw_version = version
        if not version:
            sw_version = GetVersion(self._connection)()['SW  Ver']
        logging.info(f"the ASC software version need be supported is {sw_version}")

        version = sw_version
        if sw_version not in self._versions:
            version = self._find_nearest_smaller_version(sw_version)
            logging.info(f"the version you requested {sw_version} is not in the white list, we find the nearest one {version}")
        version_module = self._versions[version]
        return self._get_command_classes(version_module)

    def _find_nearest_smaller_version(self, sw_version):
        version_numbers = [version_number for version_number, _ in self._versions.items()]
        version_numbers.append(sw_version)
        version_numbers.sort(key=self._dsc_compare)
        index = version_numbers.index(sw_version)
        if index == 1:
            logging.warning(f'current ASC version {sw_version} you are using is not in the white list, '
                            'you will use a default solution. '
                            'please contact the author if you want the version is supported officially.'
                            )
        return version_numbers[index - 1]

    def _dsc_compare(self, version):
        major, minor, build = version.split('.')
        filled_major = major.zfill(3)
        filled_minor = minor.zfill(3)
        filled_build = build.zfill(3)
        return filled_major + filled_minor + filled_build

    def _get_command_classes(self, version_moudle):
        all_classes = dict(inspect.getmembers(version_moudle, inspect.isclass))
        return {name: class_obj for name, class_obj in all_classes.items() if issubclass(class_obj, Command)}
